import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    T = int(input_data[0])
    results = []

    idx = 1
    for _ in range(T):
        S = input_data[idx]
        idx += 1
        n = len(S)
        target = "CHEF"
        k = 4

        if n < k:
            res = []
            for char in S:
                if char == '?':
                    res.append('A')
                else:
                    res.append(char)
            results.append("".join(res))
            continue

        dp = [0] * (n + 1)

        for i in range(n - k + 1):
            can_place = True
            for j in range(k):
                if S[i + j] != '?' and S[i + j] != target[j]:
                    can_place = False
                    break
            if can_place:
                dp[i] = 1

        best = [0] * (n + 1)
        for i in range(n - k, -1, -1):
            if dp[i]:
                best[i] = 1 + best[i + k]
            else:
                best[i] = best[i + 1]

        max_chef = best[0]

        res = []
        i = 0
        while i < n:
            if i <= n - k and dp[i] and best[i] == max_chef:
                for j in range(k):
                    res.append(target[j])
                i += k
                max_chef -= 1
            else:
                if S[i] == '?':
                    res.append('A')
                else:
                     res.append(S[i])
                i += 1

        results.append("".join(res))

    for r in results:
        print(r)

if __name__ == "__main__":
    solve()
